const DOC_CLASS_AR:Record<string,string>={MIZAN_ACTION_REQUIRED:'إجراء من ميزان',TENANT_ACTION_REQUIRED:'إجراء من الجهة',SECURITY_REVIEW:'مراجعة أمنية',INTEGRITY_PROTECTED:'محمي بالنزاهة',INFORMATIONAL:'للعلم',AUTO_RESOLVED:'حُلّ تلقائيًا'};
