const DOC_ACTION_AR:Record<string,string>={'notification.retry':'إعادة إرسال الإشعارات','domain.retest':'إعادة اختبار النطاق','job.retry':'إعادة تشغيل المهمة','diagnostic.bundle.generate':'توليد تقرير تشخيص','user_sessions.revoke':'إنهاء الجلسات القديمة','network.reconnect':'إعادة الاتصال بالشبكة','tenant_cache.refresh':'تحديث ذاكرة الجهة','provider.circuit_break':'كبح مزوّد متعثر','optional_ai.disable':'تعطيل وحدة ذكاء اختيارية','offline_queue.drain':'تفريغ قائمة الانتظار','integration.retest':'إعادة اختبار التكامل','grant.resume':'استئناف صلاحية','grant.suspend':'تعليق صلاحية','activation_qr.reissue':'إعادة إصدار رمز التفعيل','device.spare.assign':'إسناد جهاز احتياطي','device.assignment.invalidate':'إلغاء إسناد جهاز','safe_resync.force':'إعادة مزامنة آمنة','provider.failover':'تحويل إلى مزوّد بديل','version.block_unsafe':'منع الإصدار غير المتوافق'};
const DOC_CONF_AR:Record<string,string>={LOW:'ثقة منخفضة',MEDIUM:'ثقة متوسطة',HIGH:'ثقة عالية'};
const DOC_SAFE_AUTO=new Set(['notification.retry','network.reconnect','offline_queue.drain','tenant_cache.refresh','provider.circuit_break','optional_ai.disable','job.retry','domain.retest','integration.retest','diagnostic.bundle.generate']);
const DOC_TEXT_AR:Array<[RegExp,string]>=[[/HOST_REQUIRED/g,'لم يُضبط نطاق للجهة بعد'],[/DNS\/TLS verification unavailable/g,'تعذّر التحقق من DNS أو شهادة الأمان'],[/TENANT_SUSPENDED/g,'الجهة موقوفة'],[/TENANT_STORE_NOT_CONFIGURED/g,'سجل الجهات غير مهيأ'],[/No notification provider configured/g,'لا يوجد مزوّد إشعارات مهيأ'],[/No live competitions reported in the active window/g,'لا مسابقات حية في النافذة الحالية'],[/No live competition telemetry/g,'لا قياسات للمسابقات الحية'],[/No background job telemetry/g,'لا قياسات للمهام الخلفية'],[/No configured integration signal/g,'لا تكامل مهيأ'],[/No durable audit\/source storage signal/g,'لا تخزين دائم للتدقيق أو المصدر'],[/No edge relay configured/g,'لا مُرحّل طرفي مهيأ'],[/Tenant domain:/g,'نطاق الجهة:'],[/Live competitions/g,'المسابقات الحية'],[/Background jobs/g,'المهام الخلفية'],[/Notifications/g,'الإشعارات'],[/Identity governance/g,'حوكمة الهوية'],[/Deployment compatibility/g,'توافق النشر'],[/Devices \/ edge/g,'الأجهزة والطرف'],[/Integrations/g,'التكاملات'],[/Database \/ storage/g,'قاعدة البيانات والتخزين'],[/Firebase authentication/g,'مصادقة Firebase'],[/Tenant registry/g,'سجل الجهات']];
const docAr=(s:string,ar:boolean)=>{if(!ar||!s)return s;let out=s;for(const [re,v] of DOC_TEXT_AR)out=out.replace(re,v);return out};
const docActionLabel=(a:string,ar:boolean)=>ar?(DOC_ACTION_AR[a]||a):a;
const docIsAuto=(a:string)=>DOC_SAFE_AUTO.has(a);

