      {autoActs.slice(1).map((a:string)=><Button key={a} size="sm" variant="outline" disabled={!!busyAction} onClick={()=>void runRescue(a,primary.tenantId)}>{busyAction===a?'…':docActionLabel(a,ar)}</Button>)}
